/**
 * Per-`DeviceType` aggregate in a [`Summary`].
 */
public struct DeviceTypeCount {
    public var deviceType: DeviceType
    public var count: UInt32

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(deviceType: DeviceType, count: UInt32) {
        self.deviceType = deviceType
        self.count = count
    }
}



extension DeviceTypeCount: Equatable, Hashable {
    public static func ==(lhs: DeviceTypeCount, rhs: DeviceTypeCount) -> Bool {
        if lhs.deviceType != rhs.deviceType {
            return false
        }
        if lhs.count != rhs.count {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(deviceType)
        hasher.combine(count)
    }
}


