/**
 * Final result of a completed scan.
 */
public struct Summary {
    public var totalHosts: UInt32
    public var scannedHosts: UInt32
    public var discoveredHosts: UInt32
    public var totalOpenPorts: UInt32
    public var elapsedMs: UInt64
    public var byDeviceType: [DeviceTypeCount]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(totalHosts: UInt32, scannedHosts: UInt32, discoveredHosts: UInt32, totalOpenPorts: UInt32, elapsedMs: UInt64, byDeviceType: [DeviceTypeCount]) {
        self.totalHosts = totalHosts
        self.scannedHosts = scannedHosts
        self.discoveredHosts = discoveredHosts
        self.totalOpenPorts = totalOpenPorts
        self.elapsedMs = elapsedMs
        self.byDeviceType = byDeviceType
    }
}



extension Summary: Equatable, Hashable {
    public static func ==(lhs: Summary, rhs: Summary) -> Bool {
        if lhs.totalHosts != rhs.totalHosts {
            return false
        }
        if lhs.scannedHosts != rhs.scannedHosts {
            return false
        }
        if lhs.discoveredHosts != rhs.discoveredHosts {
            return false
        }
        if lhs.totalOpenPorts != rhs.totalOpenPorts {
            return false
        }
        if lhs.elapsedMs != rhs.elapsedMs {
            return false
        }
        if lhs.byDeviceType != rhs.byDeviceType {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(totalHosts)
        hasher.combine(scannedHosts)
        hasher.combine(discoveredHosts)
        hasher.combine(totalOpenPorts)
        hasher.combine(elapsedMs)
        hasher.combine(byDeviceType)
    }
}


