/**
 * Every error the engine can report. Exposed to Swift/Kotlin as a flat error
 * (a single foreign error type carrying a variant name + `Display` message).
 */
public enum ScanError {

    
    
    /**
     * A scan was cancelled by the caller before completion.
     */
    case Cancelled(message: String)
    
    /**
     * The operation is not possible on this platform without privileges.
     */
    case Unsupported(message: String)
    
    /**
     * A network-level failure (socket error, ICMP unreachable, drop, …).
     */
    case Network(message: String)
    
    /**
     * No scannable network interface could be found.
     */
    case NoNetwork(message: String)
    
    /**
     * The scan configuration is invalid.
     */
    case InvalidConfig(message: String)
    
    /**
     * A per-probe or overall timeout was exceeded.
     */
    case Timeout(message: String)
    
    /**
     * The feature is not yet implemented (Phase 1 stubs return this).
     */
    case NotImplemented(message: String)
    
    /**
     * An unexpected internal failure.
     */
    case Internal(message: String)
    
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeScanError: FfiConverterRustBuffer {
    typealias SwiftType = ScanError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ScanError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Cancelled(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .Unsupported(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .Network(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .NoNetwork(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .InvalidConfig(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .Timeout(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .NotImplemented(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .Internal(
            message: try FfiConverterString.read(from: &buf)
        )
        

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ScanError, into buf: inout [UInt8]) {
        switch value {

        

        
        case .Cancelled(_ /* message is ignored*/):
            writeInt(&buf, Int32(1))
        case .Unsupported(_ /* message is ignored*/):
            writeInt(&buf, Int32(2))
        case .Network(_ /* message is ignored*/):
            writeInt(&buf, Int32(3))
        case .NoNetwork(_ /* message is ignored*/):
            writeInt(&buf, Int32(4))
        case .InvalidConfig(_ /* message is ignored*/):
            writeInt(&buf, Int32(5))
        case .Timeout(_ /* message is ignored*/):
            writeInt(&buf, Int32(6))
        case .NotImplemented(_ /* message is ignored*/):
            writeInt(&buf, Int32(7))
        case .Internal(_ /* message is ignored*/):
            writeInt(&buf, Int32(8))

        
        }
    }
}


